//! Common Subexpression Elimination (CSE) post-pass on symbolic expressions.
//!
//! Scans a collection of [`Expr`] ASTs (e.g. function value, gradient outputs),
//! identifies shared non-trivial subcomputations across all outputs, and emits
//! an ordered sequence of let bindings (`_t0`, `_t1`, ...).
//!
//! This reduces redundant runtime FLOPs without needing runtime memoization or
//! complex dynamic allocation.

use crate::expr::Expr;
use std::collections::{BTreeMap, HashMap, HashSet};

/// A single intermediate let-binding generated by CSE.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LetBinding {
    /// Temporary variable identifier (e.g. `"_t0"`).
    pub name: String,
    /// The subexpression bound to this temporary.
    pub expr: Expr,
}

/// The result of performing Common Subexpression Elimination.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CseResult {
    /// Sequential list of let-bindings in topological order.
    pub bindings: Vec<LetBinding>,
    /// The updated root expressions, with shared subtrees substituted by `Expr::Var(name)`.
    pub outputs: Vec<Expr>,
}

/// Perform Common Subexpression Elimination across multiple root expressions.
pub fn eliminate_common_subexprs(exprs: &[Expr]) -> CseResult {
    // 1. Collect all existing variable names to avoid _tN shadowing
    let mut used_vars: HashSet<String> = HashSet::new();
    for expr in exprs {
        for v in expr.variables() {
            used_vars.insert(v);
        }
    }

    // 2. Count occurrences of all candidate subexpressions (excluding bound-var subtrees)
    let mut counts: BTreeMap<String, (Expr, usize)> = BTreeMap::new();
    let empty_bound = HashSet::new();
    for expr in exprs {
        count_subexprs(expr, &empty_bound, &mut counts);
    }

    // 3. Filter to subexpressions that appear >= 2 times and have node_count >= 2
    let mut candidates: Vec<(usize, String, Expr)> = counts
        .into_iter()
        .filter(|(_, (e, count))| *count >= 2 && e.node_count() >= 2)
        .map(|(key, (e, _))| (e.node_count(), key, e))
        .collect();

    // Deterministic topological order: node_count ascending, then canonical string key
    candidates.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));

    // 4. Create bindings avoiding variable shadowing
    let mut bindings = Vec::with_capacity(candidates.len());
    let mut binding_map: HashMap<Expr, String> = HashMap::new();
    let mut next_idx = 0usize;

    for (_, _, candidate) in candidates {
        let rewritten_candidate = substitute_bindings(&candidate, &binding_map);
        let mut var_name = format!("_t{next_idx}");
        while used_vars.contains(&var_name) {
            next_idx += 1;
            var_name = format!("_t{next_idx}");
        }
        used_vars.insert(var_name.clone());
        next_idx += 1;

        binding_map.insert(candidate, var_name.clone());
        bindings.push(LetBinding {
            name: var_name,
            expr: rewritten_candidate,
        });
    }

    // 5. Rewrite all outputs using the bindings
    let current_outputs: Vec<Expr> = exprs
        .iter()
        .map(|e| substitute_bindings(e, &binding_map))
        .collect();

    // 6. Prune any dead bindings (0 references across later bindings and outputs)
    let mut referenced: HashSet<String> = HashSet::new();
    for out in &current_outputs {
        for v in out.variables() {
            referenced.insert(v);
        }
    }
    let mut kept_rev = Vec::with_capacity(bindings.len());
    for b in bindings.into_iter().rev() {
        if referenced.contains(&b.name) {
            for v in b.expr.variables() {
                referenced.insert(v);
            }
            kept_rev.push(b);
        }
    }
    kept_rev.reverse();

    CseResult {
        bindings: kept_rev,
        outputs: current_outputs,
    }
}

fn contains_any_bound(expr: &Expr, bound: &HashSet<String>) -> bool {
    if bound.is_empty() {
        return false;
    }
    expr.variables().iter().any(|v| bound.contains(v))
}

fn count_subexprs(
    expr: &Expr,
    bound: &HashSet<String>,
    counts: &mut BTreeMap<String, (Expr, usize)>,
) {
    if !contains_any_bound(expr, bound) {
        let key = format!("{expr}");
        counts
            .entry(key)
            .and_modify(|(_, c)| *c += 1)
            .or_insert_with(|| (expr.clone(), 1));
    }

    match expr {
        Expr::Var(_) | Expr::Const(_) => {}
        #[cfg(feature = "bfloat")]
        Expr::Bfloat(_) => {}
        Expr::Add(a, b) | Expr::Sub(a, b) | Expr::Mul(a, b) | Expr::Div(a, b) | Expr::Pow(a, b) => {
            count_subexprs(a, bound, counts);
            count_subexprs(b, bound, counts);
        }
        Expr::Neg(a)
        | Expr::Sin(a)
        | Expr::Cos(a)
        | Expr::Tan(a)
        | Expr::Exp(a)
        | Expr::Ln(a)
        | Expr::Sqrt(a)
        | Expr::Sinh(a)
        | Expr::Cosh(a)
        | Expr::Tanh(a)
        | Expr::Asin(a)
        | Expr::Acos(a)
        | Expr::Atan(a)
        | Expr::Abs(a)
        | Expr::Factorial(a) => {
            count_subexprs(a, bound, counts);
        }
        Expr::Atan2(y, x) => {
            count_subexprs(y, bound, counts);
            count_subexprs(x, bound, counts);
        }
        Expr::Pi | Expr::E => {}
        #[cfg(feature = "complex")]
        Expr::I => {}
        Expr::Tensor(_, _) => {}
        Expr::Derivative(a, b) | Expr::Integral(a, b) => {
            let mut inner_bound = bound.clone();
            if let Expr::Var(v) = b.as_ref() {
                inner_bound.insert(v.clone());
            }
            count_subexprs(a, &inner_bound, counts);
        }
        Expr::Sum(a, b, c, d) => {
            let mut inner_bound = bound.clone();
            if let Expr::Var(v) = b.as_ref() {
                inner_bound.insert(v.clone());
            }
            count_subexprs(a, &inner_bound, counts);
            count_subexprs(c, bound, counts);
            count_subexprs(d, bound, counts);
        }
        Expr::Matrix(mat) => {
            for row in mat {
                for elem in row {
                    count_subexprs(elem, bound, counts);
                }
            }
        }
        #[cfg(feature = "specfn")]
        Expr::SpecialFn(_, args) => {
            for arg in args {
                count_subexprs(arg, bound, counts);
            }
        }
    }
}

fn substitute_bindings(expr: &Expr, binding_map: &HashMap<Expr, String>) -> Expr {
    if let Some(var_name) = binding_map.get(expr) {
        return Expr::Var(var_name.clone());
    }

    match expr {
        Expr::Var(_) | Expr::Const(_) => expr.clone(),
        #[cfg(feature = "bfloat")]
        Expr::Bfloat(_) => expr.clone(),
        Expr::Add(a, b) => Expr::add(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Sub(a, b) => Expr::sub(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Mul(a, b) => Expr::mul(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Div(a, b) => Expr::div(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Pow(a, b) => Expr::pow(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Neg(a) => Expr::neg(substitute_bindings(a, binding_map)),
        Expr::Sin(a) => Expr::sin(substitute_bindings(a, binding_map)),
        Expr::Cos(a) => Expr::cos(substitute_bindings(a, binding_map)),
        Expr::Tan(a) => Expr::tan(substitute_bindings(a, binding_map)),
        Expr::Exp(a) => Expr::exp(substitute_bindings(a, binding_map)),
        Expr::Ln(a) => Expr::ln(substitute_bindings(a, binding_map)),
        Expr::Sqrt(a) => Expr::sqrt(substitute_bindings(a, binding_map)),
        Expr::Sinh(a) => Expr::sinh(substitute_bindings(a, binding_map)),
        Expr::Cosh(a) => Expr::cosh(substitute_bindings(a, binding_map)),
        Expr::Tanh(a) => Expr::tanh(substitute_bindings(a, binding_map)),
        Expr::Asin(a) => Expr::asin(substitute_bindings(a, binding_map)),
        Expr::Acos(a) => Expr::acos(substitute_bindings(a, binding_map)),
        Expr::Atan(a) => Expr::atan(substitute_bindings(a, binding_map)),
        Expr::Abs(a) => Expr::abs(substitute_bindings(a, binding_map)),
        Expr::Atan2(y, x) => Expr::atan2(
            substitute_bindings(y, binding_map),
            substitute_bindings(x, binding_map),
        ),
        Expr::Factorial(a) => Expr::factorial(substitute_bindings(a, binding_map)),
        Expr::Pi => Expr::Pi,
        Expr::E => Expr::E,
        #[cfg(feature = "complex")]
        Expr::I => Expr::I,
        Expr::Tensor(name, indices) => Expr::tensor(name, indices.clone()),
        Expr::Derivative(a, b) => Expr::derivative(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Integral(a, b) => Expr::integral(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
        ),
        Expr::Sum(a, b, c, d) => Expr::sum(
            substitute_bindings(a, binding_map),
            substitute_bindings(b, binding_map),
            substitute_bindings(c, binding_map),
            substitute_bindings(d, binding_map),
        ),
        Expr::Matrix(mat) => {
            let mut new_mat = Vec::with_capacity(mat.len());
            for row in mat {
                let mut new_row = Vec::with_capacity(row.len());
                for elem in row {
                    new_row.push(substitute_bindings(elem, binding_map));
                }
                new_mat.push(new_row);
            }
            Expr::Matrix(new_mat)
        }
        #[cfg(feature = "specfn")]
        Expr::SpecialFn(kind, args) => Expr::SpecialFn(
            *kind,
            args.iter()
                .map(|a| substitute_bindings(a, binding_map))
                .collect(),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cse_extraction() {
        // Shared subexpression: sin(x^2)
        // e1 = sin(x^2) + 1
        // e2 = sin(x^2) * 2
        let x = Expr::var("x");
        let shared = Expr::sin(Expr::pow(x.clone(), Expr::int(2)));
        let e1 = Expr::add(shared.clone(), Expr::int(1));
        let e2 = Expr::mul(shared, Expr::int(2));

        let res = eliminate_common_subexprs(&[e1, e2]);
        assert!(!res.bindings.is_empty());
        assert_eq!(res.outputs.len(), 2);

        // One of the outputs should reference the binding
        let out_str = format!("{}", res.outputs[0]);
        assert!(out_str.contains("_t"));
    }
}
